mapper.select:
SELECT check_in AS start_date, check_out AS end_date
FROM orders
WHERE room_id = #{roomId}
  AND status <> #{cancelledOrderStatus}
  AND check_in < #{endDate}
  AND check_out > #{startDate}

  AND id <> #{excludedOrderId}

UNION ALL
SELECT start_date, end_date
FROM room_block
WHERE room_id = #{roomId}
  AND start_date < #{endDate}
  AND end_date > #{startDate}

  AND id <> #{excludedBlockId}

UNION ALL
SELECT check_in AS start_date, check_out AS end_date
FROM booking_lock
WHERE room_id = #{roomId}
  AND status = #{pendingBookingStatus}
  AND expires_at > #{now}
  AND check_in < #{endDate}
  AND check_out > #{startDate}

  AND id <> #{excludedBookingLockId}
